import{_ as t,o as a,c as s,a0 as r}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"features/prerequisites.md","filePath":"features/prerequisites.md"}'),i={name:"features/prerequisites.md"};function n(o,e,l,d,u,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><p>Prerequisites let you create dependencies between flags. &quot;Feature B should only be active if Feature A is already active.&quot; This prevents inconsistent states where a dependent feature is enabled without its dependency.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>New checkout</strong> requires <strong>payment v2</strong> to be enabled first</li><li><strong>Dark mode</strong> requires <strong>theme engine</strong> to be active</li><li><strong>Admin panel</strong> requires <strong>user.role</strong> config to be <code>&quot;admin&quot;</code></li></ul><h2 id="setting-up-prerequisites" tabindex="-1">Setting Up Prerequisites <a class="header-anchor" href="#setting-up-prerequisites" aria-label="Permalink to &quot;Setting Up Prerequisites&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Prerequisites</strong> section</li><li>Select a flag from the dropdown</li><li>Choose an operator (equals, not_equals, greater_than, less_than, contains)</li><li>Set the required value (validated against the flag&#39;s type)</li><li>Click <strong>Add</strong></li></ol><h2 id="supported-operators" tabindex="-1">Supported Operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Use Case</th></tr></thead><tbody><tr><td><code>equals</code></td><td>Flag must have this exact value</td></tr><tr><td><code>not_equals</code></td><td>Flag must NOT have this value</td></tr><tr><td><code>greater_than</code></td><td>Numeric flag must be above threshold</td></tr><tr><td><code>less_than</code></td><td>Numeric flag must be below threshold</td></tr><tr><td><code>contains</code></td><td>String flag must contain substring</td></tr></tbody></table><p>Operators are filtered by the prerequisite flag&#39;s type:</p><ul><li>Boolean flags: only <code>equals</code> / <code>not_equals</code></li><li>Number flags: all operators</li><li>String flags: <code>equals</code>, <code>not_equals</code>, <code>contains</code></li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When a config&#39;s value is requested:</p><ol><li>Each prerequisite is evaluated in order</li><li>The prerequisite flag&#39;s current resolved value is compared using the operator</li><li>If ANY prerequisite is unmet → the config returns its default value</li><li>If ALL prerequisites are met → evaluation continues to targeting/rollout</li></ol><h2 id="circular-dependency-protection" tabindex="-1">Circular Dependency Protection <a class="header-anchor" href="#circular-dependency-protection" aria-label="Permalink to &quot;Circular Dependency Protection&quot;">​</a></h2><p>The system detects and prevents:</p><ul><li><strong>Self-reference</strong> — A flag cannot require itself</li><li><strong>Circular chains</strong> — A → B → A is detected and breaks the loop</li><li><strong>Depth limits</strong> — Maximum 5 levels of prerequisite nesting</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature.checkout_v2:</span></span>
<span class="line"><span>  prerequisites:</span></span>
<span class="line"><span>    - feature.payments_v2 equals true</span></span>
<span class="line"><span>    - app.min_version greater_than 2.0</span></span>
<span class="line"><span>  value: false (default)</span></span>
<span class="line"><span>  targeting:</span></span>
<span class="line"><span>    - If user in &quot;Beta Testers&quot; → true</span></span></code></pre></div><p>This means: checkout_v2 can only be <code>true</code> if payments_v2 is already <code>true</code> AND the app version is above 2.0. Even if a user is in &quot;Beta Testers&quot;, if the prerequisites aren&#39;t met, they get <code>false</code>.</p>`,19)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
